func (a *headAppender) AppendHistogram(ref storage.SeriesRef, lset labels.Labels, t int64, h *histogram.Histogram, fh *histogram.FloatHistogram) (storage.SeriesRef, error) {
	if !a.head.opts.EnableNativeHistograms.Load() {
		return 0, storage.ErrNativeHistogramsDisabled
	}

	oooTimeWindow := a.oooTimeWindow
	minValidTime := a.minValidTime
	headMaxt := a.headMaxt
	oooNativeEnabled := a.head.opts.EnableOOONativeHistograms.Load()
	outOfBound := a.head.metrics.outOfBoundSamples
	outOfOrder := a.head.metrics.outOfOrderSamples
	tooOld := a.head.metrics.tooOldSamples
	oooObserver := a.head.metrics.oooHistogram
	if oooTimeWindow == 0 || !oooNativeEnabled {
		if t < minValidTime {
			outOfBound.WithLabelValues(sampleMetricTypeHistogram).Inc()
			return 0, storage.ErrOutOfBounds
		}
	}

	if h != nil {
		validationErr := h.Validate()
		if validationErr != nil {
			return 0, validationErr
		}
	}
	if fh != nil {
		validationErr := fh.Validate()
		if validationErr != nil {
			return 0, validationErr
		}
	}

	seriesStripes := a.head.series
	stripeCount := seriesStripes.size
	stripeMask := uint64(stripeCount - 1)
	seriesID := chunks.HeadSeriesRef(ref)
	idShard := uint64(seriesID) & stripeMask
	idLock := &seriesStripes.locks[idShard]
	idLock.RLock()
	s := seriesStripes.series[idShard][seriesID]
	idLock.RUnlock()

	var created bool
	if s == nil {
		// Ensure no empty labels have gotten through.
		lset = lset.WithoutEmpty()
		if lset.IsEmpty() {
			return 0, fmt.Errorf("empty labelset: %w", ErrInvalidSample)
		}
		var prevName, dupName string
		var seenLabel, hasDup bool
		lset.Range(func(l labels.Label) {
			if seenLabel && l.Name == prevName {
				hasDup = true
				dupName = l.Name
			}
			prevName = l.Name
			seenLabel = true
		})
		if hasDup {
			return 0, fmt.Errorf(`label name "%s" is not unique: %w`, dupName, ErrInvalidSample)
		}

		seriesHash := lset.Hash()
		existing := seriesStripes.getByHash(seriesHash, lset)
		if existing != nil {
			s = existing
		} else {
			newID := chunks.HeadSeriesRef(a.head.lastSeriesID.Inc())
			isolationDisabled := a.head.opts.IsolationDisabled
			enableSharding := a.head.opts.EnableSharding
			var err error
			s, created, err = seriesStripes.getOrSet(seriesHash, lset, func() *memSeries {
				shardHash := uint64(0)
				if enableSharding {
					shardHash = labels.StableHash(lset)
				}
				return newMemSeries(lset, newID, shardHash, isolationDisabled)
			})
			if err != nil {
				return 0, err
			}
			if created {
				a.head.metrics.seriesCreated.Inc()
				a.head.numSeries.Inc()
				a.head.postings.Add(storage.SeriesRef(newID), lset)
				if h != nil {
					s.lastHistogramValue = &histogram.Histogram{}
				} else {
					if fh != nil {
						s.lastFloatHistogramValue = &histogram.FloatHistogram{}
					}
				}
				seriesRec := record.RefSeries{}
				seriesRec.Ref = s.ref
				seriesRec.Labels = lset
				a.series = append(a.series, seriesRec)
			}
		}
	}

	if h != nil {
		s.Lock()
		// TODO(codesome): If we definitely know at this point that the sample is ooo, then optimise
		// to skip that sample from the WAL and write only in the WBL.
		_, delta, err := s.appendableHistogram(t, h, headMaxt, minValidTime, oooTimeWindow, oooNativeEnabled)
		if err != nil {
			s.pendingCommit = true
		}
		s.Unlock()
		if delta > 0 {
			oooObserver.Observe(float64(delta) / 1000)
		}
		if err != nil {
			if errors.Is(err, storage.ErrOutOfOrderSample) {
				outOfOrder.WithLabelValues(sampleMetricTypeHistogram).Inc()
			} else {
				if errors.Is(err, storage.ErrOOONativeHistogramsDisabled) {
					outOfOrder.WithLabelValues(sampleMetricTypeHistogram).Inc()
				} else {
					if errors.Is(err, storage.ErrTooOldSample) {
						tooOld.WithLabelValues(sampleMetricTypeHistogram).Inc()
					}
				}
			}
			return 0, err
		}
		histSample := record.RefHistogramSample{}
		histSample.Ref = s.ref
		histSample.T = t
		histSample.H = h
		a.histograms = append(a.histograms, histSample)
		a.histogramSeries = append(a.histogramSeries, s)
	} else {
		if fh != nil {
			s.Lock()
			// TODO(codesome): If we definitely know at this point that the sample is ooo, then optimise
			// to skip that sample from the WAL and write only in the WBL.
			_, delta, err := s.appendableFloatHistogram(t, fh, headMaxt, minValidTime, oooTimeWindow, oooNativeEnabled)
			if err == nil {
				s.pendingCommit = true
			}
			s.Unlock()
			if delta > 0 {
				oooObserver.Observe(float64(delta) / 1000)
			}
			if err != nil {
				if errors.Is(err, storage.ErrOutOfOrderSample) {
					outOfOrder.WithLabelValues(sampleMetricTypeHistogram).Inc()
				} else {
					if errors.Is(err, storage.ErrOOONativeHistogramsDisabled) {
						outOfOrder.WithLabelValues(sampleMetricTypeHistogram).Inc()
					} else {
						if errors.Is(err, storage.ErrTooOldSample) {
							tooOld.WithLabelValues(sampleMetricTypeHistogram).Inc()
						}
					}
				}
				return 0, err
			}
			floatHistSample := record.RefFloatHistogramSample{}
			floatHistSample.Ref = s.ref
			floatHistSample.T = t
			floatHistSample.FH = fh
			a.floatHistograms = append(a.floatHistograms, floatHistSample)
			a.floatHistogramSeries = append(a.floatHistogramSeries, s)
		}
	}

	if t < a.mint {
		a.mint = t
	}
	if t > a.maxt {
		a.maxt = t
	}

	return storage.SeriesRef(s.ref), nil
}

